function f = HS32_f(x)
f = 4*(x(1) - x(2)).^2 + (x(1) + 3*x(2) + x(3)).^2;
end

function g = HS32_g(x)
g = zeros(3, 1);
g(1) = 10*x(1) - 2*x(2) + 2*x(3);
g(2) = -2*x(1) + 26*x(2) + 6*x(3);
g(3) = 2*x(1) + 6*x(2) + 2*x(3);
end

function c = HS32_c(x)
c = zeros(2, 1);
c(1) = -x(1).^3 + 6*x(2) + 4*x(3) - 3;
c(2) = -x(1) - x(2) - x(3) + 1;
end

function J = HS32_J(x)
J = zeros(2, 3);
J(1, 1) = -3*x(1).^2;
J(1, 2) = 6;
J(1, 3) = 4;
J(2, 1) = -1;
J(2, 2) = -1;
J(2, 3) = -1;
end
